	@Test
	void rawPredicateSurvivesCacheHitThenEvictionRebuild() throws Exception {
		Guard predicate = new Guard();
		try (Fixture fixture = new Fixture()) {
			SlotPlan right = new FilterPlan(fixture.right, predicate, 0L);
			LeftJoinPlan optional = fixture.optional(right, null);
			assertThat(fixture.drain(optional, fixture.row)).containsExactly("payload", "payload", "payload",
					"payload");
			assertThat(predicate.calls).hasValue(2);
			assertThat(fixture.drain(optional, fixture.row)).containsExactly("payload", "payload", "payload",
					"payload");
			assertThat(predicate.calls).as("the second physical cursor uses the complete cached RHS").hasValue(2);
			OptionalMaterialization registry = fixture.registry();
			long evictions = registry.metrics().evictions();
			assertThat(registry.metrics().entries()).isEqualTo(1);
			assertThat(registry.reclaimForPreparation()).as("reclaim the unpinned repeatable materialization").isTrue();
			assertThat(registry.metrics().evictions()).isEqualTo(evictions + 1L);
			assertThat(registry.metrics().entries()).isZero();
			Throwable failure = catchThrowable(() -> assertThat(fixture.drain(optional, fixture.row))
					.containsExactly("payload", "payload", "payload", "payload"));
			assertThat(failure).as("eviction may discard raw rows, never their still-reusable predicate owner")
					.isNull();
			assertThat(predicate.calls).hasValue(4);
			assertThat(predicate.closes).as("only execution close owns the original raw predicate").hasValue(0);
		}
		assertThat(predicate.closes).hasValue(1);
	}

