	private static NativeBooleanFilter wrap(Guard guard, boolean scoped) {
		return scoped ? new ScopedNativeBooleanFilter(guard, Set.of("key", "value")) : guard;
	}

	private static final class Guard implements NativeBooleanFilter {
		final AtomicInteger calls = new AtomicInteger();
		final AtomicInteger closes = new AtomicInteger();

		@Override
		public boolean accept(RowState row) {
			if (closes.get() != 0) {
				throw new IllegalStateException("lexical predicate used after owner close");
			}
			calls.incrementAndGet();
			return true;
		}

		@Override
		public NativePredicateCapabilities capabilities() {
			return NativePredicateCapabilities.snapshot(0L, true, false);
		}

		@Override
		public void close() {
			closes.incrementAndGet();
		}
	}

